<?php declare(strict_types=1); ?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Favorilerim</title><style>body{font-family:system-ui;background:#f6f8f6;color:#26332b;margin:0}.wrap{max-width:1100px;margin:35px auto;padding:0 18px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.item{background:white;border-radius:14px;overflow:hidden}.item img{width:100%;height:190px;object-fit:cover}.item div{padding:14px}.muted{color:#6d796f}@media(max-width:700px){.grid{grid-template-columns:1fr 1fr}}@media(max-width:480px){.grid{grid-template-columns:1fr}}</style><?php require APP_ROOT . '/views/site/partials/account-theme.php'; ?></head><body><main class="wrap"><h1>Favorilerim</h1><div class="grid"><?php foreach($properties as $p): ?><article class="item"><a href="<?= e(app_url('/villa/' . rawurlencode((string)$p['slug']))) ?>"><?php if($p['cover_image']): ?><img src="<?= e(app_url('/' . ltrim((string)$p['cover_image'],'/'))) ?>" alt="<?= e($p['title']) ?>"><?php endif; ?><div><strong><?= e($p['title']) ?></strong><p class="muted"><?= e($p['city']) ?> · <?= e(number_format((float)$p['base_nightly_price'],0,',','.')) ?> <?= e($p['currency']) ?> / gece</p></div></a><form method="post" action="<?= e(app_url('/favorites/toggle')) ?>" style="padding:0 14px 14px"><?= csrf_field() ?><input type="hidden" name="property_id" value="<?= (int)$p['id'] ?>"><input type="hidden" name="return_to" value="<?= e(app_url('/favorites')) ?>"><button>Favorilerden çıkar</button></form></article><?php endforeach; ?></div><?php if(!$properties): ?><p>Henüz favori ilan eklemediniz.</p><?php endif; ?><p><a href="<?= e(app_url('/')) ?>">Konaklama keşfet</a></p><?php require APP_ROOT . '/views/site/partials/logout-button.php'; ?></main></body></html>